package autoupdate

import (
	"regexp"
	"strconv"
)

// distManifest corresponds to a subproject's dist/manifest.json (generated by
// the root build.mk build-all target).
type distManifest struct {
	Command     string            `json:"command"`
	Version     string            `json:"version"`
	BuildCommit string            `json:"build_commit"`
	Head        string            `json:"head"`
	Artifacts   map[string]string `json:"artifacts"` // file name → sha256
}

// describedVersion is the comparable form of a git describe output:
// v0.1.0-55-g12fa79d.
type describedVersion struct {
	major, minor, patch int
	commits             int // commits past the tag; 0 when the tag is hit exactly
}

var describeRe = regexp.MustCompile(
	`^v?(\d+)\.(\d+)\.(\d+)(?:-(\d+)-g[0-9a-f]+)?$`)

// parseDescribe parses a git describe version string; shapes it does not match
// (dev, a bare sha, 0.1.0-dev, etc.) return ok=false and the caller treats the
// version as unknown (degrading to plain-alignment semantics).
func parseDescribe(v string) (describedVersion, bool) {
	m := describeRe.FindStringSubmatch(v)
	if m == nil {
		return describedVersion{}, false
	}
	var out describedVersion
	var err error
	atoi := func(s string) int {
		if s == "" {
			return 0
		}
		n, e := strconv.Atoi(s)
		if e != nil {
			err = e
		}
		return n
	}
	out.major, out.minor, out.patch = atoi(m[1]), atoi(m[2]), atoi(m[3])
	out.commits = atoi(m[4])
	if err != nil {
		return describedVersion{}, false
	}
	return out, true
}

// less reports whether a is strictly lower than b: the three tag segments
// first, then the commit count past the tag when the tags are equal.
func (a describedVersion) less(b describedVersion) bool {
	if a.major != b.major {
		return a.major < b.major
	}
	if a.minor != b.minor {
		return a.minor < b.minor
	}
	if a.patch != b.patch {
		return a.patch < b.patch
	}
	return a.commits < b.commits
}

// shouldReplace decides whether to replace the local binary, based on the local
// version and the remote dist manifest version. The replacement happens only
// when the remote manifest version is strictly higher than local; whenever the
// remote version is NOT HIGHER than local (typically a stale dist on master
// that was not rebuilt) the replacement is skipped, preventing a locally built,
// higher version from being pulled back to an older artifact. When either
// side's version is unparseable it degrades to plain alignment (replace),
// matching the behavior before the manifest was introduced.
func shouldReplace(localVersion, remoteVersion string) bool {
	local, lok := parseDescribe(localVersion)
	remote, rok := parseDescribe(remoteVersion)
	if !lok || !rok {
		return true
	}
	// Same version but different hash (retagged / rewritten artifact): do not
	// replace, avoiding needless churn.
	return local.less(remote)
}
